insert into public.topics (id, subject, grade, name, unit, kazanim, sort, planned_start, curriculum) values
  ('pa.g2.matematik.place-value-hundreds', 'matematik', 2, 'Hundreds, tens, and ones', 'Numbers and Operations', 'CCSS 2.NBT.A.1: Understand that the three digits of a three-digit number represent amounts of hundreds, tens, and ones; e.g., 706 equals 7 hundreds, 0 tens, and 6 ones. Understand the following as special cases:', 0, '2026-09-02', 'us-pa'),
  ('pa.g2.matematik.skip-counting', 'matematik', 2, 'Counting and skip-counting to 1000', 'Numbers and Operations', 'CCSS 2.NBT.A.2: Count within 1000; skip-count by 5s, 10s, and 100s.', 1, '2026-09-02', 'us-pa'),
  ('pa.g2.matematik.read-write-1000', 'matematik', 2, 'Reading and writing numbers to 1000', 'Numbers and Operations', 'CCSS 2.NBT.A.3: Read and write numbers to 1000 using base-ten numerals, number names, and expanded form.', 2, '2026-09-09', 'us-pa'),
  ('pa.g2.matematik.compare-3-digit', 'matematik', 2, 'Comparing three-digit numbers', 'Numbers and Operations', 'CCSS 2.NBT.A.4: Compare two three-digit numbers based on meanings of the hundreds, tens, and ones digits, using >, =, and < symbols to record the results of comparisons.', 3, '2026-09-09', 'us-pa'),
  ('pa.g2.matematik.add-sub-20', 'matematik', 2, 'Adding and subtracting within 20', 'Algebraic Concepts', 'CCSS 2.OA.B.2: Fluently add and subtract within 20 using mental strategies. By end of Grade 2, know from memory all sums of two one-digit numbers.', 4, '2026-09-16', 'us-pa'),
  ('pa.g2.matematik.odd-even', 'matematik', 2, 'Odd and even numbers', 'Algebraic Concepts', 'CCSS 2.OA.C.3: Determine whether a group of objects (up to 20) has an odd or even number of members, e.g., by pairing objects or counting them by 2s; write an equation to express an even number as a sum of two equal addends.', 5, '2026-09-23', 'us-pa'),
  ('pa.g2.matematik.add-sub-100', 'matematik', 2, 'Adding and subtracting within 100', 'Numbers and Operations', 'CCSS 2.NBT.B.5: Fluently add and subtract within 100 using strategies based on place value, properties of operations, and/or the relationship between addition and subtraction.', 6, '2026-10-07', 'us-pa'),
  ('pa.g2.matematik.add-four-2-digit', 'matematik', 2, 'Adding up to four two-digit numbers', 'Numbers and Operations', 'CCSS 2.NBT.B.6: Add up to four two-digit numbers using strategies based on place value and properties of operations.', 7, '2026-10-14', 'us-pa'),
  ('pa.g2.matematik.word-problems-100', 'matematik', 2, 'Word problems within 100', 'Algebraic Concepts', 'CCSS 2.OA.A.1: Use addition and subtraction within 100 to solve one- and two-step word problems involving situations of adding to, taking from, putting together, taking apart, and comparing, with unknowns in all positions, e.g., by using drawings and equations with a symbol for the unknown number to represent the problem.', 8, '2026-10-21', 'us-pa'),
  ('pa.g2.matematik.measure-length', 'matematik', 2, 'Measuring length with tools', 'Measurement, Data, and Probability', 'CCSS 2.MD.A.1: Measure the length of an object by selecting and using appropriate tools such as rulers, yardsticks, meter sticks, and measuring tapes.', 9, '2026-11-04', 'us-pa'),
  ('pa.g2.matematik.different-units', 'matematik', 2, 'Measuring with different units', 'Measurement, Data, and Probability', 'CCSS 2.MD.A.2: Measure the length of an object twice, using length units of different lengths for the two measurements; describe how the two measurements relate to the size of the unit chosen.', 10, '2026-11-04', 'us-pa'),
  ('pa.g2.matematik.estimate-length', 'matematik', 2, 'Estimating lengths', 'Measurement, Data, and Probability', 'CCSS 2.MD.A.3: Estimate lengths using units of inches, feet, centimeters, and meters.', 11, '2026-11-11', 'us-pa'),
  ('pa.g2.matematik.compare-lengths', 'matematik', 2, 'Comparing lengths', 'Measurement, Data, and Probability', 'CCSS 2.MD.A.4: Measure to determine how much longer one object is than another, expressing the length difference in terms of a standard length unit.', 12, '2026-11-11', 'us-pa'),
  ('pa.g2.matematik.length-word-problems', 'matematik', 2, 'Length word problems', 'Measurement, Data, and Probability', 'CCSS 2.MD.B.5: Use addition and subtraction within 100 to solve word problems involving lengths that are given in the same units, e.g., by using drawings (such as drawings of rulers) and equations with a symbol for the unknown number to represent the problem.', 13, '2026-11-18', 'us-pa'),
  ('pa.g2.matematik.number-line', 'matematik', 2, 'The number line', 'Measurement, Data, and Probability', 'CCSS 2.MD.B.6: Represent whole numbers as lengths from 0 on a number line diagram with equally spaced points corresponding to the numbers 0, 1, 2, …, and represent whole-number sums and differences within 100 on a number line diagram.', 14, '2026-11-18', 'us-pa'),
  ('pa.g2.matematik.add-sub-1000', 'matematik', 2, 'Adding and subtracting within 1000', 'Numbers and Operations', 'CCSS 2.NBT.B.7: Add and subtract within 1000, using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction; relate the strategy to a written method. Understand that in adding or subtracting three-digit numbers, one adds or subtracts hundreds and hundreds, tens and tens, ones and ones; and sometimes it is necessary to compose or decompose tens or hundreds.', 15, '2026-12-02', 'us-pa'),
  ('pa.g2.matematik.mental-10-100', 'matematik', 2, 'Adding and subtracting 10 or 100 in your head', 'Numbers and Operations', 'CCSS 2.NBT.B.8: Mentally add 10 or 100 to a given number 100—900, and mentally subtract 10 or 100 from a given number 100—900.', 16, '2026-12-09', 'us-pa'),
  ('pa.g2.matematik.explain-strategies', 'matematik', 2, 'Explaining addition and subtraction strategies', 'Numbers and Operations', 'CCSS 2.NBT.B.9: Explain why addition and subtraction strategies work, using place value and the properties of operations.', 17, '2026-12-09', 'us-pa'),
  ('pa.g2.matematik.line-plots', 'matematik', 2, 'Line plots of measurements', 'Measurement, Data, and Probability', 'CCSS 2.MD.D.9: Generate measurement data by measuring lengths of several objects to the nearest whole unit, or by making repeated measurements of the same object. Show the measurements by making a line plot, where the horizontal scale is marked off in whole-number units.', 18, '2027-01-13', 'us-pa'),
  ('pa.g2.matematik.picture-bar-graphs', 'matematik', 2, 'Picture graphs and bar graphs', 'Measurement, Data, and Probability', 'CCSS 2.MD.D.10: Draw a picture graph and a bar graph (with single-unit scale) to represent a data set with up to four categories. Solve simple put-together, take-apart, and compare problems using information presented in a bar graph.', 19, '2027-01-20', 'us-pa'),
  ('pa.g2.matematik.money', 'matematik', 2, 'Money: dollars and coins', 'Measurement, Data, and Probability', 'CCSS 2.MD.C.8: Solve word problems involving dollar bills, quarters, dimes, nickels, and pennies, using and ¢ symbols appropriately.', 20, '2027-02-03', 'us-pa'),
  ('pa.g2.matematik.telling-time', 'matematik', 2, 'Telling time to five minutes', 'Measurement, Data, and Probability', 'CCSS 2.MD.C.7: Tell and write time from analog and digital clocks to the nearest five minutes, using a.m. and p.m.', 21, '2027-02-24', 'us-pa'),
  ('pa.g2.matematik.shapes', 'matematik', 2, 'Shapes and their attributes', 'Geometry', 'CCSS 2.G.A.1: Recognize and draw shapes having specified attributes, such as a given number of angles or a given number of equal faces. Identify triangles, quadrilaterals, pentagons, hexagons, and cubes.', 22, '2027-03-17', 'us-pa'),
  ('pa.g2.matematik.equal-shares', 'matematik', 2, 'Halves, thirds, and fourths', 'Geometry', 'CCSS 2.G.A.3: Partition circles and rectangles into two, three, or four equal shares, describe the shares using the words halves, thirds, half of, a third of, etc., and describe the whole as two halves, three thirds, four fourths. Recognize that equal shares of identical wholes need not have the same shape.', 23, '2027-03-24', 'us-pa'),
  ('pa.g2.matematik.arrays', 'matematik', 2, 'Arrays and equal groups', 'Algebraic Concepts', 'CCSS 2.OA.C.4: Use addition to find the total number of objects arranged in rectangular arrays with up to 5 rows and up to 5 columns; write an equation to express the total as a sum of equal addends.', 24, '2027-04-14', 'us-pa'),
  ('pa.g2.matematik.rows-columns', 'matematik', 2, 'Rows and columns of squares', 'Geometry', 'CCSS 2.G.A.2: Partition a rectangle into rows and columns of same-size squares and count to find the total number of them.', 25, '2027-04-21', 'us-pa'),
  ('pa.g4.matematik.place-value-ten-times', 'matematik', 4, 'Place value: ten times as much', 'Numbers and Operations', 'CCSS 4.NBT.A.1: Recognize that in a multi-digit whole number, a digit in one place represents ten times what it represents in the place to its right. For example, recognize that 700 ÷ 70 = 10 by applying concepts of place value and division.', 0, '2026-09-02', 'us-pa'),
  ('pa.g4.matematik.big-numbers', 'matematik', 4, 'Reading, writing, and comparing big numbers', 'Numbers and Operations', 'CCSS 4.NBT.A.2: Read and write multi-digit whole numbers using base-ten numerals, number names, and expanded form. Compare two multi-digit numbers based on meanings of the digits in each place, using >, =, and < symbols to record the results of comparisons.', 1, '2026-09-09', 'us-pa'),
  ('pa.g4.matematik.rounding', 'matematik', 4, 'Rounding', 'Numbers and Operations', 'CCSS 4.NBT.A.3: Use place value understanding to round multi-digit whole numbers to any place.', 2, '2026-09-09', 'us-pa'),
  ('pa.g4.matematik.add-sub-multi-digit', 'matematik', 4, 'Adding and subtracting multi-digit numbers', 'Numbers and Operations', 'CCSS 4.NBT.B.4: Fluently add and subtract multi-digit whole numbers using the standard algorithm.', 3, '2026-09-16', 'us-pa'),
  ('pa.g4.matematik.mult-comparison', 'matematik', 4, 'Multiplication as comparison', 'Algebraic Concepts', 'CCSS 4.OA.A.1: Interpret a multiplication equation as a comparison, e.g., interpret 35 = 5 × 7 as a statement that 35 is 5 times as many as 7 and 7 times as many as 5. Represent verbal statements of multiplicative comparisons as multiplication equations.', 4, '2026-09-30', 'us-pa'),
  ('pa.g4.matematik.comparison-word-problems', 'matematik', 4, 'Comparison word problems', 'Algebraic Concepts', 'CCSS 4.OA.A.2: Multiply or divide to solve word problems involving multiplicative comparison, e.g., by using drawings and equations with a symbol for the unknown number to represent the problem, distinguishing multiplicative comparison from additive comparison.', 5, '2026-09-30', 'us-pa'),
  ('pa.g4.matematik.unit-conversions', 'matematik', 4, 'Measurement units and conversions', 'Measurement, Data, and Probability', 'CCSS 4.MD.A.1: Know relative sizes of measurement units within one system of units including km, m, cm; kg, g; lb, oz.; l, ml; hr, min, sec. Within a single system of measurement, express measurements in a larger unit in terms of a smaller unit. Record measurement equivalents in a two column table. For example, know that 1 ft is 12 times as long as 1 in. Express the length of a 4 ft snake as 48 in. Generate a conversion table for feet and inches listing the number pairs (1, 12), (2, 24), (3, 36), …', 6, '2026-10-07', 'us-pa'),
  ('pa.g4.matematik.measurement-word-problems', 'matematik', 4, 'Measurement word problems', 'Measurement, Data, and Probability', 'CCSS 4.MD.A.2: Use the four operations to solve word problems involving distances, intervals of time, liquid volumes, masses of objects, and money, including problems involving simple fractions or decimals, and problems that require expressing measurements given in a larger unit in terms of a smaller unit. Represent measurement quantities using diagrams such as number line diagrams that feature a measurement scale.', 7, '2026-10-14', 'us-pa'),
  ('pa.g4.matematik.multi-digit-multiplication', 'matematik', 4, 'Multi-digit multiplication', 'Numbers and Operations', 'CCSS 4.NBT.B.5: Multiply a whole number of up to four digits by a one-digit whole number, and multiply two two-digit numbers, using strategies based on place value and the properties of operations. Illustrate and explain the calculation by using equations, rectangular arrays, and/or area models.', 8, '2026-10-21', 'us-pa'),
  ('pa.g4.matematik.division-remainders', 'matematik', 4, 'Division with remainders', 'Numbers and Operations', 'CCSS 4.NBT.B.6: Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors, using strategies based on place value, the properties of operations, and/or the relationship between multiplication and division. Illustrate and explain the calculation by using equations, rectangular arrays, and/or area models.', 9, '2026-11-04', 'us-pa'),
  ('pa.g4.matematik.multi-step-word-problems', 'matematik', 4, 'Multi-step word problems', 'Algebraic Concepts', 'CCSS 4.OA.A.3: Solve multistep word problems posed with whole numbers and having whole-number answers using the four operations, including problems in which remainders must be interpreted. Represent these problems using equations with a letter standing for the unknown quantity. Assess the reasonableness of answers using mental computation and estimation strategies including rounding.', 10, '2026-11-11', 'us-pa'),
  ('pa.g4.matematik.factors-multiples', 'matematik', 4, 'Factors, multiples, and primes', 'Algebraic Concepts', 'CCSS 4.OA.B.4: Find all factor pairs for a whole number in the range 1—100. Recognize that a whole number is a multiple of each of its factors. Determine whether a given whole number in the range 1—100 is a multiple of a given one-digit number. Determine whether a given whole number in the range 1—100 is prime or composite.', 11, '2026-11-18', 'us-pa'),
  ('pa.g4.matematik.patterns', 'matematik', 4, 'Number and shape patterns', 'Algebraic Concepts', 'CCSS 4.OA.C.5: Generate a number or shape pattern that follows a given rule. Identify apparent features of the pattern that were not explicit in the rule itself. For example, given the rule "Add 3" and the starting number 1, generate terms in the resulting sequence and observe that the terms appear to alternate between odd and even numbers. Explain informally why the numbers will continue to alternate in this way.', 12, '2026-12-02', 'us-pa'),
  ('pa.g4.matematik.area-perimeter', 'matematik', 4, 'Area and perimeter', 'Measurement, Data, and Probability', 'CCSS 4.MD.A.3: Apply the area and perimeter formulas for rectangles in real world and mathematical problems. For example, find the width of a rectangular room given the area of the flooring and the length, by viewing the area formula as a multiplication equation with an unknown factor.', 13, '2026-12-09', 'us-pa'),
  ('pa.g4.matematik.equivalent-fractions', 'matematik', 4, 'Equivalent fractions', 'Numbers and Operations', 'CCSS 4.NF.A.1: Explain why a fraction a/b is equivalent to a fraction (n × a)/(n × b) by using visual fraction models, with attention to how the number and size of the parts differ even though the two fractions themselves are the same size. Use this principle to recognize and generate equivalent fractions.', 14, '2027-01-06', 'us-pa'),
  ('pa.g4.matematik.compare-fractions', 'matematik', 4, 'Comparing fractions', 'Numbers and Operations', 'CCSS 4.NF.A.2: Compare two fractions with different numerators and different denominators, e.g., by creating common denominators or numerators, or by comparing to a benchmark fraction such as 1/2. Recognize that comparisons are valid only when the two fractions refer to the same whole. Record the results of comparisons with symbols >, =, or <, and justify the conclusions, e.g., by using a visual fraction model.', 15, '2027-01-13', 'us-pa'),
  ('pa.g4.matematik.add-sub-fractions', 'matematik', 4, 'Adding and subtracting fractions', 'Numbers and Operations', 'CCSS 4.NF.B.3: Understand a fraction a/b with a > 1 as a sum of fractions 1/b.', 16, '2027-01-27', 'us-pa'),
  ('pa.g4.matematik.fraction-times-whole', 'matematik', 4, 'Multiplying a fraction by a whole number', 'Numbers and Operations', 'CCSS 4.NF.B.4: Apply and extend previous understandings of multiplication to multiply a fraction by a whole number.', 17, '2027-02-10', 'us-pa'),
  ('pa.g4.matematik.line-plots-fractions', 'matematik', 4, 'Line plots with fractions', 'Measurement, Data, and Probability', 'CCSS 4.MD.B.4: Make a line plot to display a data set of measurements in fractions of a unit (1/2, 1/4, 1/8). Solve problems involving addition and subtraction of fractions by using information presented in line plots. For example, from a line plot find and interpret the difference in length between the longest and shortest specimens in an insect collection.', 18, '2027-02-24', 'us-pa'),
  ('pa.g4.matematik.tenths-hundredths', 'matematik', 4, 'Tenths and hundredths', 'Numbers and Operations', 'CCSS 4.NF.C.5: Express a fraction with denominator 10 as an equivalent fraction with denominator 100, and use this technique to add two fractions with respective denominators 10 and 100.', 19, '2027-03-03', 'us-pa'),
  ('pa.g4.matematik.decimals', 'matematik', 4, 'Decimal notation', 'Numbers and Operations', 'CCSS 4.NF.C.6: Use decimal notation for fractions with denominators 10 or 100. For example, rewrite 0.62 as 62/100; describe a length as 0.62 meters; locate 0.62 on a number line diagram.', 20, '2027-03-10', 'us-pa'),
  ('pa.g4.matematik.compare-decimals', 'matematik', 4, 'Comparing decimals', 'Numbers and Operations', 'CCSS 4.NF.C.7: Compare two decimals to hundredths by reasoning about their size. Recognize that comparisons are valid only when the two decimals refer to the same whole. Record the results of comparisons with the symbols >, =, or <, and justify the conclusions, e.g., by using a visual model.', 21, '2027-03-17', 'us-pa'),
  ('pa.g4.matematik.lines-angles', 'matematik', 4, 'Points, lines, rays, and angles', 'Geometry', 'CCSS 4.G.A.1: Draw points, lines, line segments, rays, angles (right, acute, obtuse), and perpendicular and parallel lines. Identify these in two-dimensional figures.', 22, '2027-04-07', 'us-pa'),
  ('pa.g4.matematik.angle-concepts', 'matematik', 4, 'Understanding angles', 'Measurement, Data, and Probability', 'CCSS 4.MD.C.5: Recognize angles as geometric shapes that are formed wherever two rays share a common endpoint, and understand concepts of angle measurement:', 23, '2027-04-14', 'us-pa'),
  ('pa.g4.matematik.protractor', 'matematik', 4, 'Measuring angles with a protractor', 'Measurement, Data, and Probability', 'CCSS 4.MD.C.6: Measure angles in whole-number degrees using a protractor. Sketch angles of specified measure.', 24, '2027-04-14', 'us-pa'),
  ('pa.g4.matematik.adding-angles', 'matematik', 4, 'Adding angle measures', 'Measurement, Data, and Probability', 'CCSS 4.MD.C.7: Recognize angle measure as additive. When an angle is decomposed into non-overlapping parts, the angle measure of the whole is the sum of the angle measures of the parts. Solve addition and subtraction problems to find unknown angles on a diagram in real world and mathematical problems, e.g., by using an equation with a symbol for the unknown angle measure.', 25, '2027-04-21', 'us-pa'),
  ('pa.g4.matematik.classify-shapes', 'matematik', 4, 'Classifying shapes', 'Geometry', 'CCSS 4.G.A.2: Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or the presence or absence of angles of a specified size. Recognize right triangles as a category, and identify right triangles.', 26, '2027-05-05', 'us-pa'),
  ('pa.g4.matematik.symmetry', 'matematik', 4, 'Lines of symmetry', 'Geometry', 'CCSS 4.G.A.3: Recognize a line of symmetry for a two-dimensional figure as a line across the figure such that the figure can be folded along the line into matching parts. Identify line-symmetric figures and draw lines of symmetry.', 27, '2027-05-12', 'us-pa'),
  ('pa.g7.matematik.add-sub-rationals', 'matematik', 7, 'Adding and subtracting rational numbers', 'Numbers and Operations', 'CCSS 7.NS.A.1: Apply and extend previous understandings of addition and subtraction to add and subtract rational numbers; represent addition and subtraction on a horizontal or vertical number line diagram.', 0, '2026-09-02', 'us-pa'),
  ('pa.g7.matematik.mult-div-rationals', 'matematik', 7, 'Multiplying and dividing rational numbers', 'Numbers and Operations', 'CCSS 7.NS.A.2: Apply and extend previous understandings of multiplication and division and of fractions to multiply and divide rational numbers.', 1, '2026-09-23', 'us-pa'),
  ('pa.g7.matematik.rational-problems', 'matematik', 7, 'Problems with rational numbers', 'Numbers and Operations', 'CCSS 7.NS.A.3: Solve real-world and mathematical problems involving the four operations with rational numbers.', 2, '2026-10-14', 'us-pa'),
  ('pa.g7.matematik.unit-rates', 'matematik', 7, 'Unit rates', 'Numbers and Operations', 'CCSS 7.RP.A.1: Compute unit rates associated with ratios of fractions, including ratios of lengths, areas and other quantities measured in like or different units. For example, if a person walks 1/2 mile in each 1/4 hour, compute the unit rate as the complex fraction \frac{\frac{1}{2}}{\frac{1}{4}} miles per hour, equivalently 2 miles per hour.', 3, '2026-10-28', 'us-pa'),
  ('pa.g7.matematik.proportional-relationships', 'matematik', 7, 'Proportional relationships', 'Numbers and Operations', 'CCSS 7.RP.A.2: Recognize and represent proportional relationships between quantities.', 4, '2026-11-04', 'us-pa'),
  ('pa.g7.matematik.percent-problems', 'matematik', 7, 'Ratio and percent problems', 'Numbers and Operations', 'CCSS 7.RP.A.3: Use proportional relationships to solve multistep ratio and percent problems.', 5, '2026-11-18', 'us-pa'),
  ('pa.g7.matematik.equivalent-expressions', 'matematik', 7, 'Equivalent expressions', 'Algebraic Concepts', 'CCSS 7.EE.A.1: Apply properties of operations as strategies to add, subtract, factor, and expand linear expressions with rational coefficients.', 6, '2026-12-09', 'us-pa'),
  ('pa.g7.matematik.rewriting-expressions', 'matematik', 7, 'Rewriting expressions', 'Algebraic Concepts', 'CCSS 7.EE.A.2: Understand that rewriting an expression in different forms in a problem context can shed light on the problem and how the quantities in it are related. For example, a + 0.05a = 1.05a means that "increase by 5%" is the same as "multiply by 1.05."', 7, '2026-12-16', 'us-pa'),
  ('pa.g7.matematik.multi-step-problems', 'matematik', 7, 'Multi-step problems', 'Algebraic Concepts', 'CCSS 7.EE.B.3: Solve multi-step real-life and mathematical problems posed with positive and negative rational numbers in any form (whole numbers, fractions, and decimals), using tools strategically. Apply properties of operations to calculate with numbers in any form; convert between forms as appropriate; and assess the reasonableness of answers using mental computation and estimation strategies. For example: If a woman making 25 an hour gets a 10% raise, she will make an additional 1/10 of her salary an hour, or 2.50, for a new salary of 27.50. If you want to place a towel bar 9\frac{3}{4} inches long in the center of a door that is 27\frac{1}{2} inches wide, you will need to place the bar about 9 inches from each edge; this estimate can be used as a check on the exact computation.', 8, '2027-01-13', 'us-pa'),
  ('pa.g7.matematik.equations-inequalities', 'matematik', 7, 'Equations and inequalities', 'Algebraic Concepts', 'CCSS 7.EE.B.4: Use variables to represent quantities in a real-world or mathematical problem, and construct simple equations and inequalities to solve problems by reasoning about the quantities.', 9, '2027-01-27', 'us-pa'),
  ('pa.g7.matematik.scale-drawings', 'matematik', 7, 'Scale drawings', 'Geometry', 'CCSS 7.G.A.1: Solve problems involving scale drawings of geometric figures, including computing actual lengths and areas from a scale drawing and reproducing a scale drawing at a different scale.', 10, '2027-02-17', 'us-pa'),
  ('pa.g7.matematik.constructions', 'matematik', 7, 'Drawing shapes and triangles', 'Geometry', 'CCSS 7.G.A.2: Draw (freehand, with ruler and protractor, and with technology) geometric shapes with given conditions. Focus on constructing triangles from three measures of angles or sides, noticing when the conditions determine a unique triangle, more than one triangle, or no triangle.', 11, '2027-02-24', 'us-pa'),
  ('pa.g7.matematik.cross-sections', 'matematik', 7, 'Slicing 3D figures', 'Geometry', 'CCSS 7.G.A.3: Describe the two-dimensional figures that result from slicing three-dimensional figures, as in plane sections of right rectangular prisms and right rectangular pyramids.', 12, '2027-03-03', 'us-pa'),
  ('pa.g7.matematik.circles', 'matematik', 7, 'Circles: area and circumference', 'Geometry', 'CCSS 7.G.B.4: Know the formulas for the area and circumference of a circle and use them to solve problems; give an informal derivation of the relationship between the circumference and area of a circle.', 13, '2027-03-10', 'us-pa'),
  ('pa.g7.matematik.angle-relationships', 'matematik', 7, 'Angle relationships', 'Geometry', 'CCSS 7.G.B.5: Use facts about supplementary, complementary, vertical, and adjacent angles in a multi-step problem to write and solve simple equations for an unknown angle in a figure.', 14, '2027-03-17', 'us-pa'),
  ('pa.g7.matematik.area-volume', 'matematik', 7, 'Area, surface area, and volume', 'Geometry', 'CCSS 7.G.B.6: Solve real-world and mathematical problems involving area, volume and surface area of two- and three-dimensional objects composed of triangles, quadrilaterals, polygons, cubes, and right prisms.', 15, '2027-03-24', 'us-pa'),
  ('pa.g7.matematik.samples', 'matematik', 7, 'Samples and populations', 'Measurement, Data, and Probability', 'CCSS 7.SP.A.1: Understand that statistics can be used to gain information about a population by examining a sample of the population; generalizations about a population from a sample are valid only if the sample is representative of that population. Understand that random sampling tends to produce representative samples and support valid inferences.', 16, '2027-04-14', 'us-pa'),
  ('pa.g7.matematik.sample-inferences', 'matematik', 7, 'Making inferences from samples', 'Measurement, Data, and Probability', 'CCSS 7.SP.A.2: Use data from a random sample to draw inferences about a population with an unknown characteristic of interest. Generate multiple samples (or simulated samples) of the same size to gauge the variation in estimates or predictions. For example, estimate the mean word length in a book by randomly sampling words from the book; predict the winner of a school election based on randomly sampled survey data. Gauge how far off the estimate or prediction might be.', 17, '2027-04-14', 'us-pa'),
  ('pa.g7.matematik.compare-data', 'matematik', 7, 'Comparing data sets', 'Measurement, Data, and Probability', 'CCSS 7.SP.B.3: Informally assess the degree of visual overlap of two numerical data distributions with similar variabilities, measuring the difference between the centers by expressing it as a multiple of a measure of variability. For example, the mean height of players on the basketball team is 10 cm greater than the mean height of players on the soccer team, about twice the variability (mean absolute deviation) on either team; on a dot plot, the separation between the two distributions of heights is noticeable.', 18, '2027-04-21', 'us-pa'),
  ('pa.g7.matematik.center-variability', 'matematik', 7, 'Center and variability', 'Measurement, Data, and Probability', 'CCSS 7.SP.B.4: Use measures of center and measures of variability for numerical data from random samples to draw informal comparative inferences about two populations. For example, decide whether the words in a chapter of a seventh-grade science book are generally longer than the words in a chapter of a fourth-grade science book.', 19, '2027-04-21', 'us-pa'),
  ('pa.g7.matematik.probability-scale', 'matematik', 7, 'Probability between 0 and 1', 'Measurement, Data, and Probability', 'CCSS 7.SP.C.5: Understand that the probability of a chance event is a number between 0 and 1 that expresses the likelihood of the event occurring. Larger numbers indicate greater likelihood. A probability near 0 indicates an unlikely event, a probability around 1/2 indicates an event that is neither unlikely nor likely, and a probability near 1 indicates a likely event.', 20, '2027-05-05', 'us-pa'),
  ('pa.g7.matematik.experimental-probability', 'matematik', 7, 'Experimental probability', 'Measurement, Data, and Probability', 'CCSS 7.SP.C.6: Approximate the probability of a chance event by collecting data on the chance process that produces it and observing its long-run relative frequency, and predict the approximate relative frequency given the probability. For example, when rolling a number cube 600 times, predict that a 3 or 6 would be rolled roughly 200 times, but probably not exactly 200 times.', 21, '2027-05-05', 'us-pa'),
  ('pa.g7.matematik.probability-models', 'matematik', 7, 'Probability models', 'Measurement, Data, and Probability', 'CCSS 7.SP.C.7: Develop a probability model and use it to find probabilities of events. Compare probabilities from a model to observed frequencies; if the agreement is not good, explain possible sources of the discrepancy.', 22, '2027-05-12', 'us-pa'),
  ('pa.g7.matematik.compound-events', 'matematik', 7, 'Compound events', 'Measurement, Data, and Probability', 'CCSS 7.SP.C.8: Find probabilities of compound events using organized lists, tables, tree diagrams, and simulation.', 23, '2027-05-19', 'us-pa')
